sys_script_include.script:
var StatusReportPRJMJR = Class.create();
StatusReportPRJMJR.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    statusreport: function(filter) {
		var unique = [];
        var latestStatus = {}; 
        var statusr = new GlideRecord('project_status');
        statusr.addEncodedQuery(filter);
        statusr.orderByDesc('as_on'); 
        statusr.query();

        while (statusr.next()) {
            var projectId = statusr.project.toString();
            var statusDate = statusr.as_on;

            if (!latestStatus[projectId] || statusDate > latestStatus[projectId].date) {
                latestStatus[projectId] = {
                    sys_id: statusr.sys_id.toString(),
                    date: statusDate
                };
            }
        }

        for (var project in latestStatus) {
            //gs.print('Project: ' + project + ' - Latest sys_id: ' + latestStatus[project].sys_id + ' (as_on: ' + latestStatus[project].date + ')');
			unique.push(latestStatus[project].sys_id);
        }

		return unique ;
    },

    type: 'StatusReportPRJMJR'
});
